const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const BASE = { openai: 'https://api.openai.com/v1', gemini: 'https://generativelanguage.googleapis.com/v1beta/openai', glm: 'https://api.z.ai/api/paas/v4' };
const provider = String(ai.provider || '').trim().toLowerCase();
if (!BASE[provider]) throw new Error('provider_not_allowed');
const model = String(ai.model || '').trim();
const apiKey = String(ai.apiKey || '');
if (!model || !apiKey) throw new Error('ai_config_missing');
let temperature = Number(ai.temperature);
if (!Number.isFinite(temperature)) temperature = 0.2;
temperature = Math.max(0, Math.min(1, temperature));
const systemPrompt = String(ai.systemPrompt || '').trim();
const userPrompt = String(ai.userPrompt || '').trim();
const messages = [];
if (systemPrompt) messages.push({ role: 'system', content: systemPrompt });
messages.push({ role: 'user', content: userPrompt });
return [{ json: { provider, model, baseUrl: BASE[provider], apiKey, temperature, messages } }];

let r = $input.first().json || {};
if (Array.isArray(r)) r = r[0] || {};
if (r.error) return [{ json: { ok: false, errorCode: 'provider_error' } }];
const choices = Array.isArray(r.choices) ? r.choices : [];
let content = String((choices[0] && choices[0].message && choices[0].message.content) || '').trim();
if (!content) return [{ json: { ok: false, errorCode: 'empty_output' } }];
const fence = content.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) content = fence[1].trim();
const first = content.indexOf('{');
const last = content.lastIndexOf('}');
if (first >= 0 && last > first) content = content.slice(first, last + 1);
let output;
try { output = JSON.parse(content); } catch (_) { return [{ json: { ok: false, errorCode: 'invalid_json' } }]; }
const usage = r.usage || {};
return [{ json: { ok: true, output, model: String(r.model || ''), usage: { promptTokens: Number(usage.prompt_tokens || 0), completionTokens: Number(usage.completion_tokens || 0), totalTokens: Number(usage.total_tokens || 0) } } }];
